                    SQLExpr::Value(ValueWithSpan { value: v, .. }) => {
                        self.visit_any_value(v, Some(op))
                    },
                    _ => Err(polars_err!(SQLInterface: "array element {:?} is not supported", e)),
                },
                SQLExpr::Array(values) => {
                    let srs = self.array_expr_to_series(&values.elem)?;
                    Ok(AnyValue::List(srs))
                },
                // typed literals (eg: `DATE '2020-01-01'`) and casts (eg: `'42'::int`
                // or `CAST('42' AS INT)`) are evaluated to a scalar and used as-is.
                SQLExpr::TypedString { .. } | SQLExpr::Cast { .. } => {
                    self.eval_expr_to_any_value(e)
                },
                _ => Err(polars_err!(SQLInterface: "array element {:?} is not supported", e)),
            }?
            .into_static();
            array_elements.push(val);
        }

        // all elements of an array literal must share a consistent dtype.
        let mut expected: Option<DataType> = None;
        for av in &array_elements {
            if av.is_null() {
                continue;
